INSERT INTO verticalizzazionibase(modulo, descrizione) VALUES('WS_LOGIN','Se attivata permette di sovrascrivere la User Id con la quale eseguire la login durante le chiamate via web service');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO,PARAMETRO,DESCRIZIONE) VALUES('WS_LOGIN','USERID_OPERATORE','User Id dell''operatore');
INSERT INTO VERTICALIZZAZIONIBASE (MODULO, DESCRIZIONE) VALUES ('PAYER_ADAPTER', 'Contiene i parametri usati dal componente PAYER_ADAPTER per l''integrazione di Back Office con PayER (Sistema dei pagamenti Regione Emilia Romagna)');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PAYER_ADAPTER', 'CODICE_UTENTE', 'Indica il valore che viene inviato da PayER nel tag Request_ResponseBase.codiceUtente. Serve per recuperare il modulo software per filtrare gli oneri (nel caso non venga specificato anche il parametro di verticalizzazione PAYER_ADAPTER.CODICE_UFFICIO)');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PAYER_ADAPTER', 'CODICE_UFFICIO', 'Indica il valore che viene inviato da PayER nel tag Request_ResponseBase.codiceUfficio. Serve per recuperare il modulo software per filtrare gli oneri (se questo valore non è specificato (oppure è uguale a TT) allora il software viene recuperato da PAYER_ADAPTER.CODICE_UTENTE e se questo è nullo o uguale a TT allora le scadenze vengono estratte per tutti i moduli)');	
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PAYER_ADAPTER', 'NUM_CCACCREDITOPAGAMENTO', 'Contiene il valore che viene inviato dal PAYER_ADAPTER alla richiesta di RecuperaDatiBollettinoRequest. Rappresenta il valore del Conto Corrente di accreditamento che verrà presentato al cittadino. Il valore viene inserito in RecuperaDatiBollettinoResponse.numeroCCAccreditoPagamento. Se configurato un valore per software allora il software sarà recuperato secondo la logica di quanto scritto in PAYER_ADAPTER.CODICE_UFFICIO altrimenti sarà preso il valore del software TT. In caso di mancata valorizzazione di questo parametro PAYER_ADAPTER lancera'' un errore alla richiesta da parte di PayER');
INSERT INTO COMUNIASSOCIAZIONI(CODICEASSOCIAZIONE,ASSOCIAZIONE) VALUES ('AL081','UNIONE DEI COMUNI PIAN DEL BRUSCOLO');
INSERT INTO COMUNIASSOCIAZIONI(CODICEASSOCIAZIONE,ASSOCIAZIONE) VALUES ('AE730','UNIONE DEI COMUNI BASSA ROMAGNA');
INSERT INTO COMUNIASSOCIAZIONI(CODICEASSOCIAZIONE,ASSOCIAZIONE) VALUES ('AF715','UNIONE DELLA VAL CONCA');
INSERT INTO COMUNIASSOCIAZIONI(CODICEASSOCIAZIONE,ASSOCIAZIONE) VALUES ('AF401','UNIONE DEI COMUNI DI OSTRA E RIPE');
INSERT INTO FO_ARJ_STEPS_BASE (NOME_STEP, LINK_FUNZIONE, TITOLO, DESCRIZIONE,FLAG_OBBLIGATORIO, DIPENDE_DA_STEP, INCOMPATIBILE_CON_STEP, ORDINE_DEFAULT) VALUES ('BENVENUTO','../nuovaistanza/benvenuto.htm','Benvenuto','Le pagine che seguono rappresentano il percorso guidato per la presentazione on line di una istanza.<br />Il percorso per inviare la pratica on line è composto da una serie di step (schede).<br />In fondo a destra si trova la numerazione delle pagine e in nero viene evidenziato lo step che si sta compilando.',0,NULL,NULL, 1);
INSERT INTO FO_ARJ_STEPS_BASE (NOME_STEP, LINK_FUNZIONE, TITOLO, DESCRIZIONE,FLAG_OBBLIGATORIO, DIPENDE_DA_STEP, INCOMPATIBILE_CON_STEP, ORDINE_DEFAULT) VALUES ('INFORMATIVA_PRIVACY','../nuovaistanza/informativa.htm','Informativa privacy','INFORMATIVA AI SENSI DELL''ART. 13 DEL DECRETO LEGISLATIVO N. 196/2003, "CODICE IN MATERIA DI PROTEZIONE DEI DATI PERSONALI"
INSERT INTO FO_ARJ_STEPS_BASE (NOME_STEP, LINK_FUNZIONE, TITOLO, DESCRIZIONE,FLAG_OBBLIGATORIO, DIPENDE_DA_STEP, INCOMPATIBILE_CON_STEP, ORDINE_DEFAULT) VALUES ('INSERIMENTO_ANAGRAFICHE','../anagrafe/richiedente.htm','Inserimento anagrafiche','In questa scheda vanno inseriti tutti i soggetti, persone fisiche e giuridiche, coinvolti nella pratica che si sta presentando. I soggetti possono essere l''interessato, l''azienda coinvolta, l''intermediario ...',0,NULL,NULL,3);
INSERT INTO FO_ARJ_STEPS_BASE (NOME_STEP, LINK_FUNZIONE, TITOLO, DESCRIZIONE,FLAG_OBBLIGATORIO, DIPENDE_DA_STEP, INCOMPATIBILE_CON_STEP, ORDINE_DEFAULT) VALUES ('LOCALIZZAZIONE','../nuovaistanza/localizzazione.htm','Localizzazione','È possibile in questa sezione inserire nel campo "Indirizzo" la localizzazione dell''intervento. <br />Selezionare un indirizzo compreso nello stradario comunale dopo aver digitato nel campo "Denominazione" almeno due lettere della localizzazione, quindi completare l''indirizzo indicando il civico ed eventuali note.<br />Se l''intervento ricade in una zona ancora non censita digitare "NON DEFINITO" nel campo "Denominazione" e nel campo "Note" immettere una localizzazione di massima (frazione, zona, etc.)',0,NULL,NULL,4);
INSERT INTO FO_ARJ_STEPS_BASE (NOME_STEP, LINK_FUNZIONE, TITOLO, DESCRIZIONE,FLAG_OBBLIGATORIO, DIPENDE_DA_STEP, INCOMPATIBILE_CON_STEP, ORDINE_DEFAULT) VALUES ('INTERVENTO','../nuovaistanza/intervento.htm','Intervento','In questa sezione è possibile individuare l''attività della propria azienda secondo la classificazione adottata dallo sportello unico del comune',0,NULL,NULL,5);
INSERT INTO FO_ARJ_STEPS_BASE (NOME_STEP, LINK_FUNZIONE, TITOLO, DESCRIZIONE,FLAG_OBBLIGATORIO, DIPENDE_DA_STEP, INCOMPATIBILE_CON_STEP, ORDINE_DEFAULT) VALUES ('PROCEDIMENTI','../nuovaistanza/procedimenti.htm','Procedimenti','In questa sezione è possibile attivare gli endoprocedimenti utili al completamento dell''istanza.<br />Gli endo-procedimenti già selezionati sono proposti dal sistema in base alla compilazione degli step precedenti.',0,NULL,NULL,6);
INSERT INTO FO_ARJ_STEPS_BASE (NOME_STEP, LINK_FUNZIONE, TITOLO, DESCRIZIONE,FLAG_OBBLIGATORIO, DIPENDE_DA_STEP, INCOMPATIBILE_CON_STEP, ORDINE_DEFAULT) VALUES ('SCHEDE','../nuovaistanzaschede/list.htm','Schede','...',0,NULL,NULL,7);
INSERT INTO FO_ARJ_STEPS_BASE (NOME_STEP, LINK_FUNZIONE, TITOLO, DESCRIZIONE,FLAG_OBBLIGATORIO, DIPENDE_DA_STEP, INCOMPATIBILE_CON_STEP, ORDINE_DEFAULT) VALUES ('ALLEGATI','../nuovaistanza/allegati.htm','Allegati','Gli allegati che riportano il simbolo (<b>*</b>) sono obbligatori. Sarà cura del richiedente o della persona incaricata allegare i documenti proposti nell''elenco. <br />Il bottone "Sfoglia" permette di cercare il documento da caricare , una volta selezionato cliccare sulla voce "Carica". <br />',0,NULL,NULL,8);
INSERT INTO FO_ARJ_STEPS_BASE(NOME_STEP,LINK_FUNZIONE, TITOLO,DESCRIZIONE,FLAG_OBBLIGATORIO,DIPENDE_DA_STEP,INCOMPATIBILE_CON_STEP, ORDINE_DEFAULT) VALUES
