INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO,PARAMETRO,DESCRIZIONE) VALUES('AREA_RISERVATA','AREA_RISERVATA_JAVA_ATTIVA','Indica se e'' attivo l''applicativo area riservata java. Valori ammessi S (Si) N (No)');
INSERT INTO CLMENU_JAVA (ID,DESCRIZIONE,PAGINA,MENULINK, SOFTWARE, JSP, LAYOUTTESTI, VERTICALIZZAZIONE,SOFTWAREESCLUSI, LINK_STANDARD,TIPO_FUNZIONALITA ) VALUES (1006, 'Tipologie attività', 'iattivitatipologie/list.htm?software=SOFTWARE', '0AZM', '*','JAVA', 0, NULL, 'PR,FI,AB','iattivitatipologie/list.htm?software=SOFTWARE', 'E');
INSERT into CATEGORIEEVENTIBASE (ID, DESCRIZIONE) VALUES('AR-NUOVO-ENTE','Ente non trovato nella lista degli enti locali');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE(MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PROTOCOLLO_SIGEDO','TIPO_DOCUMENTO_PRINCIPALE','Specificare il valore del tipo documento dell''allegato principale, questo dato può essere omesso IN quanto non obbligatorio');                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE(MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PROTOCOLLO_SIGEDO','APPLICATIVO_PROTOCOLLO','Indica il nome dell''applicativo del protocollo, questa voce sarà inserita dentro il file segnatura.xml dentro l''attributo -nome- di <ApplicativoProtocollo/>. NB. Se lasciato vuoto o non attivato prenderà il valore inserito dentro il parametro CODICEENTE');                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE(MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PROTOCOLLO_SIGEDO','CODICEENTE','E'' il codice dell''ente per il quale protocollare, questo parametro va usato nell''autenticazione al web service insieme al parametro USERNAME_WS e PASSWORD_WS');                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE(MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PROTOCOLLO_SIGEDO','CODICE_AOO','E'' il codice dell''Area Organizzativa Omogenea, definisce l''ambito per cui protocollare, in particolare, deve essere fornito dai responsabili di protocollo.');                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE(MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PROTOCOLLO_SIGEDO','INVIA_SEGNATURA','Se valorizzato a 1 consente, in fase di protocollazione istanza o movimento da backoffice, di allegare il file di profilazione (segnatura.xml) che sarebbe il file che viene inviato al web service per eseguire la protocollazione. Questa funzionalità viene usata nel momento in cui il cliente decide che nessun file allegato deve essere inviato al web service, che però ne richiede necessariamente almeno uno.; se valorizzato a 0 o non valorizzato non esegue nessuna funzionalità.');                                                                                                                                                                                                                                                                                                             
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE(MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PROTOCOLLO_SIGEDO','USERNAME_WS','E'' lo username che serve per autenticarsi al web service di protocollazione, va usato insieme al parametro CODICEENTE e PASSWORD_WS.');                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE(MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PROTOCOLLO_SIGEDO','PASSWORD_WS','E'' la password che serve per autenticarsi al web service di protocollazione, va usato insieme al parametro CODICEENTE e USERNAME_WS.');                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE(MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PROTOCOLLO_SIGEDO','TIPO_DOCUMENTO_ALLEGATO','Specificare il valore del tipo documento degli allegati secondari, ossia quei documenti allegati al protocollo escluso quello principale, questo parametro non è obbligatorio.');                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE(MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PROTOCOLLO_SIGEDO','UO','Indica l''ufficio di smistamento del protocollo, questa voce sarà inserita dentro il file segnatura.xml dentro il nodo <ApplicativoProtocollo> valorizzando un nuovo parametro con nome -UO-. ');                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE(MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PROTOCOLLO_SIGEDO','URL_PROTO','E'' l''endpoint utilizzato per invocare il web service di protocollazione.');                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE(MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PROTOCOLLO_SIGEDO','URL_QUERYSERVICE','E'' l''endpoint utilizzato per invocare il web service di ricerche, tramite questo servizio è possibile cercare i protocolli, gli allegati, i mittenti e destinatari, da usare in fase di LeggiProtocollo, questo servizio ha la particolarità che restituisce diversi dati in base ai metadati passati e determinati dai parametri AREA e MODELLO, ad esempio se AREA viene lasciato vuoto e MODELLO valorizzato con @PROTO cerca un protocollo altrimenti con diversi valori potrebbe cercare allegati oppure mittenti e destinatari.');                                                                                                                                                                                                                                                                   
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE(MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PROTOCOLLO_SIGEDO','AREA_LEGGIPROTO','Parametro area usato per la ricerca di un protocollo invocando i servizi presenti sull''endpoint del parametro URL_QUERYSERVICE. E'' una sezione del documentale dedicata ad un particolare compito applicativo con dei modelli atti a tale scopo; ad esempio l’area SEGRETERIA contiene i modelli del protocollo');                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE(MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PROTOCOLLO_SIGEDO','MODELLO_LEGGIPROTO','Parametro modello usato per la ricerca di un protocollo invocando i servizi presenti sull''endpoint del parametro URL_QUERYSERVICE. Rappresenta la tipologia di modello di riferimento (in relazione all’area scelta); ciascuna tipologia è dotata di una collezione di attributi specifici e/o metadati da valorizzare, ad esempio anno e numero per la ricerca di un protocollo');                                                                                                                                                                                                                                                                                                                                                                                                                       
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE(MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PROTOCOLLO_SIGEDO','STATO','Parametro stato usato per invocare i servizi presenti sull''endpoint del parametro URL_QUERYSERVICE, questo parametro è fisso per tutte le ricerche e indica se cercare un protocollo in stato BO (Bozza) oppure CO (Completo)');                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE(MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PROTOCOLLO_SIGEDO','AREA_ALLEGATI','Parametro area usato per la ricerca degli allegati secondari di uno specifico protocollo, cercato in precedenza, invocando i servizi presenti sull''endpoint del parametro URL_QUERYSERVICE. E'' una sezione del documentale dedicata ad un particolare compito applicativo con dei modelli atti a tale scopo; ad esempio l’area SEGRETERIA contiene i modelli del protocollo');                                                                                                                                                                                                                                                                                                                                                                                                                                
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE(MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PROTOCOLLO_SIGEDO','MODELLO_ALLEGATI','Parametro modello usato per la ricerca degli allegati di uno specifico protocollo, cercato in precedenza, invocando i servizi presenti sull''endpoint del parametro URL_QUERYSERVICE. Rappresenta la tipologia di modello di riferimento (in relazione all’area scelta); ciascuna tipologia è dotata di una collezione di attributi specifici e/o metadati da valorizzare, ad esempio anno e numero per la ricerca di un protocollo');                                                                                                                                                                                                                                                                                                                                                                       
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE(MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PROTOCOLLO_SIGEDO','AREA_SOGGETTI','Parametro area usato per la ricerca soggetti (mittenti/destinatari) di uno specifico protocollo, cercato in precedenza, invocando i servizi presenti sull''endpoint del parametro URL_QUERYSERVICE. E'' una sezione del documentale dedicata ad un particolare compito applicativo con dei modelli atti a tale scopo; ad esempio l’area SEGRETERIA contiene i modelli del protocollo');                                                                                                                                                                                                                                                                                                                                                                                                                         
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE(MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PROTOCOLLO_SIGEDO','MODELLO_SOGGETTI','Parametro modello usato per la ricerca soggetti (mittenti/destinatari) di uno specifico protocollo, cercato in precedenza, invocando i servizi presenti sull''endpoint del parametro URL_QUERYSERVICE. Rappresenta la tipologia di modello di riferimento (in relazione all’area scelta); ciascuna tipologia è dotata di una collezione di attributi specifici e/o metadati da valorizzare, ad esempio anno e numero per la ricerca di un protocollo');                                                                                                                                                                                                                                                                                                                                                      
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE(MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PROTOCOLLO_SIGEDO','OPERATORE_RICERCHE','Parametro operatore usato nei metadati per eseguire tutti i tipi di ricerche, invocando i servizi presenti sull''endpoint del parametro URL_QUERYSERVICE. Valore fisso da passare che però non ha niente a che fare ne con lo username del web service ne con gli operatori di protocollo.');                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE(MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PROTOCOLLO_SIGEDO','USERNAME_QUERYSERVICE','Username usato per l''autenticazione del web service di ricerche QUERYSERVICE.');                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE(MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PROTOCOLLO_SIGEDO','PASSWORD_QUERYSERVICE','Password usata per l''autenticazione del web service di ricerche QUERYSERVICE.');                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
INSERT INTO VERTICALIZZAZIONIBASE(MODULO, DESCRIZIONE) VALUES ('PROTOCOLLO_DELTA', 'Se attivato consente di eseguire la protocollazione con il protocollo proprietario di Delta Informatica, con questo tipo di protocollo abbiamo la possibilità di eseguire delle prove in ambiente di test fornito proprio dalla Società Delta Informatica, in particolare l''applicativo si trova all''indirizzo: http://crm.deltainf.it/protocollo/, NB.: la protocollazione può avvenire solo tramite un unico operatore in quanto il web service richiede, oltre che il paramtro username, anche la password che verrà inserita tra i parametri, quindi non è possibile usare i segnalibri nel parametro Operatore della verticalizzazione PROTOCOLLO_ATTIVO');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE(MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PROTOCOLLO_DELTA', 'URL', 'Specificare in questo parametro l''end point del web service di protocollazione');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE(MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PROTOCOLLO_DELTA', 'PASSWORD', 'Indica la password dell''utente che protocolla, questo dato può essere usato solamente nel caso in cui l''utente protocollatore sia solamente uno, quindi non è possibile usare i segnalibri nel parametro OPERATORE della verticalizzazione PROTOCOLLO_ATTIVO così come spiegato anche sulla descrizione della verticalizzazione PROTOCOLLO_DELTA');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE(MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PROTOCOLLO_DELTA', 'REGISTRO', 'Indica il registro (o AOO è la stessa cosa) da usare durante la fase di protocollazione, è un dato alfanumerico di tre caratteri, ad esempio in ambiente di test il valore è 011');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE(MODULO, PARAMETRO, DESCRIZIONE) VALUES('PROTOCOLLO_DELTA', 'CODICE_CC','Indica il codice per conoscenza da utilizzare in fase di protocollazione. Sulla maschera di protocollazione è presente un campo a tendina denominato -Trasmesso per- legato all''anagrafica (Mittente / Destinatario), questo campo viene popolato dai valori presenti nella tabella PROTOCOLLO_MODALITAINVIO, indicando il codice in questo campo, quando l''operatore selezionerà nella tendina -Trasmesso per- il valore con lo stesso codice, l''anagrafica selezionata sarà considerata per conoscenza.');
INSERT INTO MAPOGGETTI (NOMETABELLA, NOMECAMPO) VALUES ('FO_ARJ_DOMANDE','CODICEOGGETTO_RIEPILOGO');
INSERT INTO MAPOGGETTI (NOMETABELLA, NOMECAMPO) VALUES ('FO_ARJ_DOMANDE_ONERI','CODICEOGGETTO_XML');
INSERT INTO MAPOGGETTI (NOMETABELLA, NOMECAMPO) VALUES ('FO_ARJ_DOMANDE_ONERI','CODICEOGGETTO_PDF');
INSERT INTO FO_ARJ_STEPS_BASE (NOME_STEP, LINK_FUNZIONE, TITOLO, DESCRIZIONE, FLAG_OBBLIGATORIO, DIPENDE_DA_STEP,INCOMPATIBILE_CON_STEP, ORDINE_DEFAULT) VALUES ('ONERI','../nuovaistanzaoneri/oneri.htm','Riepilogo diritti/oneri','Questa scheda riepiloga quanti diritti di istruttoria/oneri/bolli devono essere corrisposti con riferimento all''intervento e agli endoprocedimenti attivati. Per i pagamenti per i quali si possiede già la ricevuta si ricorda che questa deve essere firmata digitalmente. I pagamenti possono essere effettuati mediante bollettino utilizzando le seguenti coordinate: <b>c/c postale n. XXXX intestato a Comune di XXXXX- Direzione XXXXXX.</b>',0,'INTERVENTO', NULL, 9);
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE(MODULO, PARAMETRO, DESCRIZIONE) VALUES('PROTOCOLLO_DELTA', 'USERNAME', 'Indica lo username dell''utente che protocolla, e fa parte dell''autenticazione dell''operatore già registrato nell''applicativo di protocollo; ogni chiamata al web service necessita come argomento il valore di questo parametro.') ; 
INSERT INTO VERTICALIZZAZIONIBASE (MODULO, DESCRIZIONE) VALUES ('SISTEMAPAGAMENTI_ATTIVO_FO','Indica se nel frontoffice è attivato un sistema di pagamento per permettere all''utente collegato di poter effettuare pagamenti telematici. (es: PAGAMENTI_MIP_RPCSUAP)');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES('SISTEMAPAGAMENTI_ATTIVO_FO','TIPOSISTEMA','Indicare quale sistema di pagamento è attivo (es: PAGAMENTI_MIP_RPCSUAP)');
INSERT INTO VERTICALIZZAZIONIBASE (MODULO, DESCRIZIONE) VALUES ('PAGAMENTI_MIP_RPCSUAP','Il sistema di pagamento di frontend "modulo incassi e pagamento" del progetto RPC_SUAP');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES('PAGAMENTI_MIP_RPCSUAP','URLSERVERPAGAMENTO','indica l''URL del Server di Pagamento'); 
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES('PAGAMENTI_MIP_RPCSUAP','INDIRIZZOPROXY','Indica l''indirizzo del proxy (eventuale) usato dai componenti di comunicazione col sistema di pagamento'); 
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES('PAGAMENTI_MIP_RPCSUAP','PORTAPROXY','Indica la porta del proxy (eventuale) usato dai componenti di comunicazione col sistema di pagamento'); 
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES('PAGAMENTI_MIP_RPCSUAP','WINDOW_MINUTES','Finestra temporale per la validazione del messaggio'); 
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES('PAGAMENTI_MIP_RPCSUAP','IDSERVIZIO','Identificativo del servizio chiamante.'); 
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES('PAGAMENTI_MIP_RPCSUAP','IDENTIFICATIVO_COMPONENTE','L''identificativo del componente nelle chiamate verso il sistema di pagamenti'); 
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES('PAGAMENTI_MIP_RPCSUAP','PORTALEID','Identifica il sito dei servizi nei confronti del sistema dei pagamenti'); 
