INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE(MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PROTOCOLLO_DOCAREA', 'INVIA_NOMEFILE_ATTACH', 'Indica se il nome file degli allegati deve essere inviato come id sull''attachment della richiesta soap, questa esigenza è venuta a crearsi con il protocollo SAGA al Comune di Lucca in quanto il web service non riusciva a leggere il nome del file in quanto non veniva inviato come id dell''attachment, in altri ambiti DOCAREA invece sembra funzionare correttamente, se valorizzato a 1 allora il sistema invia il nome file come id, (vedi anche il parametro NOMEFILE_ORIGINE della verticalizzazione PROTOCOLLO_ATTIVO) qualsiasi altro valore non invia il nome file sull''id dell''attachment');